    multipliers = [[] for _ in range(21)]
    for i, g in enumerate(gcd):
        if g != 1:
            multipliers[g].append(i)

    dp = [-1] * (k + 1)
    dp[0] = 0

    for g in multipliers:
        for i in reversed(range(len(g))):
