import math
from typing import List

def is_possible_plates(n: int, a: int, b: int, plates: List[int]) -> bool:
    import heapq
    dirty, dry = [i for i in range(n)], []
    empty = []
    for i in range(n):
        if plates[i] == min(plates):
            continue
        heapq.heappush(dry, i)
    for i in range(n):
        if i != max(heapq.heappop(dry)):
            return False
        heapq.heappush(empty, i)
    for i in range(a):
        if len(empty) < b:
            return False
        idx1 = heapq.heappop(empty)
        idx2 = heapq.heappop(heapq.heappop(dry) - b + 1)
        heapq.heappush(heapq.heappushpop(heapq.heappushpop(dry, idx2), idx1))
    return True

