from random import randint

MOD = 998244353
def calculate_rank(rank):
    while rank > 0:
        rank %= MOD
    return rank

def update_rank(tree):
    num_nodes = len(tree)
    rank_arr = [1] * num_nodes
    for i in range(num_nodes-1):
        i_edge = randint(0, num_nodes-1)
        while tree[i_edge] in set(tree[:i_edge]) or tree[i_edge] in set(tree[i_edge+1:]):
            i_edge = randint(0, num_nodes-1)
        node, neighbor = tree[i_edge]
        neighbor_rank = calculate_rank(rank_arr[:node-1])
        neighbor_rank %= MOD
        rank_arr[node-1] += neighbor_rank
        rank_arr[neighbor-1] -= neighbor_rank
        for neighbor in tree[i_edge+1:]:
            rank_arr[neighbor[0]-1] += neighbor_rank
            rank_arr[neighbor[1]-1] -= neighbor_rank
    rank_sum = sum(rank_arr)
    stoprank = calculate_rank(rank_sum)
    stoprank %= MOD
    return stoprank

def query(n, edges):
    tree = [i+1 for i in range(n)]
    for edge in edges:
        add_edge(tree, edge)
    root = solve(tree, 0)
    if not root:
        return 0
    return update_rank(tree) * (2**(n-1))

def add_edge(tree, edge):
    i = randint(0, (len(tree) - 2) * 2)
    if edge[0] == edge[1]:
        return
    if randint(0, 1) == 0:
        tree.insert(i, edge)
    else:
        tmp = tree[i]
        tree[i] = edge
        tree.insert(len(tree) - 1, tmp)

def solve(tree, i=0):
    num_nodes = len(tree)
    if num_nodes <= 3:
        return [i]
    else:
        head = -1
        for j in range(num_nodes):
            if j not in set(tree[:i]):
                if head == -1:
                    head = j
                else:
                    return [head, j]
        head = solve(tree, head)
        return head

