def find_longest_cool_sequence(name_length, name):
    # Initialize dynamic programming array
    dp = [1] * name_length
    # Forward pass to find LCS (longest common subsequence)
    for i in range(1, name_length):
        for j in range(i):
            if name[i] == name[j] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1

    # Reverse pass to find cool sequence lengths
    max_length = 0
    for i in range(name_length - 1, -1, -1):
        if dp[i] >= dp[max_length]:
            max_length = i

    return dp[max_length]

