        return
    if rank[root1] > rank[root2]:
        root1, root2 = root2, root1
    parent[root1] = root2
    if rank[root1] == rank[root2]:
        rank[root2] += 1

def connected(p, q):
    return find(p) == find(q)

# Rerooting algorithm to count edges from p to root, rank path cost to sub-root
