    max_cos, ans = 0, 0
    for n in nodes:
        if not connected(p, n):
            max_cos = max(max_cos, dist)
            ans += n * dist
    for n in nodes:
        if connected(p, n):
            max_cos = max(max_cos, dist)
        else:
            max_cos = max(max_cos, dist + dfs(n, dist+1))
    return ans - (max_cos if dist == 0 else 0)

