from math import ceil

def minimal_string_checkerboard(s, k):
    n = len(s)
    m = ceil(ceil(log(n, 2)) / 2)
    changed = []

    for bit in range(m + 1):
        shift = 2**bit % n
        changed.append([0] * n)

        for i in range(0, n, 2**bit):
            for j in range(0, n, 2**bit):
                if s[i:i + shift] == s[i + shift:i + 2 * shift]:
                    changes = 1
                elif s[i:i + shift] == s[i + shift:]:
                    changes = -1

                if s[i:i + shift] == s[i + shift: n]:
                    if s[i + 1:i + 2 * shift] == s[i + 2 * shift: n]:
                        changes -= 1
                    elif s[i + 1:i + 2 * shift] == s[i + 2 * shift: n - 1]:
                        changes += 1

                score = changes + s[i:i + shift].count('a') + s[i + shift:i + 2 * shift].count('c')
                new_val = min(s[i:i + shift], s[i + shift:i + 2 * shift], key=lambda a: (score, a))

                if score > 0:
                    changed[bit][j+k] = 1

                changed[bit][j+shift] = s[j+shift: j+k].count('a')
                changed[bit][j+2*shift] = s[j+2*shift: j+k].count('a')
                changed[bit][j+k+shift] = s[j+k+shift: j+k+2*shift].count('a')
                changed[bit][j+k+2*shift] = s[j+k+2*shift: j+k+3*shift].count('a')

                changed[bit][j+k] += 1
                changed[bit][j+k+shift] += 1
                changed[bit][j+k+2*shift] += 1
                changed[bit][j+k+3*shift] += 1

                changed[bit][j+i] = changed[bit][j+i+shift] = changed[bit][j+i+2*shift] = changed[bit][j+i+k] = changes

            for j in range(n, j, -2**bit):
                changed[bit][j] = 0

    return ''.join([s[s.index('a')][i % (2**bit):i % ((2**bit) * 2)] for i in range(n) for bit in range(m + 1) if changed[bit][i]])

