from collections import deque

def longest_cool_sequence(company_name):
    n = len(company_name)
    logo_substrings = set()

    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = company_name[i:j]
            if substring != '' and is_cool_substring(substring, company_name):
                logo_substrings.add(substring)

    queue = deque(list(logo_substrings))
    cool_sequence_lengths = [1] * len(logo_substrings)

    for i in range(1, len(logo_substrings)):
        heapq.heappush(queue, (cool_sequence_lengths[i - 1], logo_substrings[i]))

        while queue and cool_sequence_lengths[queue[0][1][0]] > cool_sequence_lengths[i]:
            heapq.heappop(queue)

        if queue and queue[0][1] == logo_substrings[i]:
            while queue and queue[0][1] == logo_substrings[i]:
                heapq.heappop(queue)

    return max(cool_sequence_lengths)

def is_cool_substring(substring, company_name):
    left = right = 0
    for _ in range(len(company_name)):
        right += 1
        while substring[left:right] not in company_name[left:right]:
            right -= 1
        if right < len(company_name):
            left += 1
            while substring[left:right] in company_name[left:left + len(substring)]:
                right = max(right + 1, left + len(substring))
    return substring[left:right] == ''

