def max_value_of_path(tree, weights):
    def dfs(node, par):
        inc_sum = [0]
        for child in tree[node]:
            if child != par:
                inc_sum.append(inc_sum[-1] + weights[child])
        max_val = 0
        for branch in range(2, len(inc_sum) + 2):
            for i in range(len(inc_sum) - branch + 1):
                cur = 0
                for j in range(i, i + branch - 1):
                    cur += inc_sum[j]
                max_val = max(max_val, cur)
        return max_value[node] = max(cur, cur * 2 + dfs(node, -1)) if max_value[node] == -1 else max_value[node]

    edges = defaultdict(list)
    for u, v in tree:
        edges[u].append(v)
        edges[v].append(u)

    nodes = set()
    for node in range(1, len(tree) + 1):
        if node in nodes:
            continue
        nodes.add(node)
