from math import gcd
from collections import defaultdict

def find_mxcps(n, nums):
    mod_divisors = []
    for divisor in range(1, n+1):
        total_devides = 0
        for num in nums:
            for rest_num in nums:
                if rest_num != num and gcd(num, rest_num) == divisor:
                    total_devides += 1
        mod_divisors.append((divisor, total_devides))
    mod_divisors.sort(key=lambda x: (x[0], -x[1]))
    return [cp for _, cp in mod_divisors]

