import math

def check_triangle_area(a, b, c):
    return abs(a[0]*(b[1]-c[1]) + b[0]*(c[1]-a[1]) + c[0]*(a[1]-b[1]))/2

def divide_triangle(p, q):
    a, b = sorted([p, q])
    for x in range(2, len(p)):
        index = (math.atan2(p[x][1] - p[-1][1], p[x][0] - p[-1][0]) - math.atan2(p[1][1] - p[-2][1], p[1][0] - p[-2][0])) % (2*math.pi)
        c = sorted([p[index], p[(index+1)%len(p)]] + [q, q[1]])
        if check_triangle_area(c[0], c[1], c[2]) == 0:
            return math.pi, c[0], c[1]  # area is zero, no common boundary
        if check_triangle_area(p[0], p[-1], b) <= check_triangle_area(c[0], c[1], c[2]) <= 0.999:
            return math.atan2(q[1] - p[index+1][1], q[0] - p[index+1][0]), p[index+1], q[0]  # no part contains the edge of the triangle
        if -0.999 <= check_triangle_area(c[0], c[1], c[2]) <= check_triangle_area(p[0], p[-1], b):
            if c[0][0] < c[1][0]:  # distance to the edges might be needed, the star is the opposite one
                a, b = b, a
            return index, a, b  # can be cut at this segment

def solution(n, queries):
    segments = []
    for _ in range(n):
        segments.append(divide_triangle(vertices, vertices[2]))
    for i in range(1, int(n/3) + 1):
        for j in range(i, len(segments), 2):
            cut = 0
            poly = vertices[:]
            for k in range(j-1, len(segments)):
                if k % 2 == 0:
                    cut += 1 + check_triangle_area(poly, vertices, poly[2])
                    # corner checking messed up
                    while poly[0][0] != vertices[0][0] or poly[0][1] != vertices[0][1]:
                        poly[3:-3] = [poly[2], (vertices[0][1] - vertices[1][1])/(vertices[0][0] - vertices[1][0]) * (vertices[2][0] - vertices[0][0]) + vertices[0][1], vertices[0][-1]]
                    cut += 1
            # print(cut, segments[j-1][1], vertices, poly)
            if cut == i * 4:  # if cut is equal to the corner cutting rule 4x
                return segments[j-1][1], segments[j][2], segments[j:][j%2+1]


