from typing import List

def stack_washing_plates(n: int, a: int, b: int, sizes: List[int]) -> str:
    from math import ceil

    if n < a + b:
        return "NO"

    dirty_stack = sizes[:]
    intermediate_stack = [None] * a
    dryer_stack = [None] * b

    operations = 0
    while dirty_stack:
        max_plate_size = max(dirty_stack)
        if dirty_stack != sorted(dirty_stack):
            # Not in the correct order, keep trying from max
            dirty_stack.remove(max_plate_size)
            dirty_stack.append(max_plate_size)
            operations += 1
        else:
            if operations % 2 == 0:
                # Wash first, then move to dryer
                break
            else:
                # Move from stack to dryer, then from dryer first in stack
                clean_stack = [c for c in dirty_stack if c < max_plate_size]
                dryer_index = 0
                for c in list(intermediate_stack)[::-1]:
                    if max_plate_size > dirty_stack[0]:
                        fourth_place = max_plate_size
                    else:
                        fourth_place = dirty_stack.pop(0)
                    if fourth_place in clean_stack:
                        clean_stack.remove(fourth_place)
                    else:
                        clean_stack.append(fourth_place)
                    dryer_stack[dryer_index] = fourth_place
                    dryer_index += 1

                    if len(clean_stack) + len(dryer_stack) == b:
                        break
                else:
                    return "NO"

                num_clean = len(clean_stack)
                dirty_stack += clean_stack
                hihgher_clean_stack = [(len(intermediate_stack) - i) for i in range(num_clean)]
                for i in range(num_clean):
                    intermediate_stack.insert(i, higher_clean_stack.pop(0))

                if num_clean < b:
                    operation = 2 if (operations % 2) == 0 else 1
                    for c in dirty_stack[:b - num_clean]:
                        intermediate_stack.append(c)
                    for c in dryer_stack[-num_clean:]:
                        dirty_stack.append(c)
                    for i in range(num_clean):
                        intermediate_stack[i] = dirty_stack[b - i]

                    if len(dryer_stack) < b - num_clean:
                        dryer_stack = [None] * (b - num_clean) + dryer_stack

                    operations += 2
                else:
                    return "NO"

        operations += 1

    return f"YES\n{operations}\n{''.join([f'{o[0]} {o[1]}\n' for o in [(1, a)] + [(1, 1)] * (operations - 1) + [(2, b)]])}"

# Example usage
print(stack_washing_plates(6, 4, 6, [2, 3, 6, 4, 1, 5]))
print(stack_washing_plates(6, 3, 2, [2, 3, 6, 4, 1, 5]))
