import math

def find_consecutive_divisors(n):
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            count += 1
            if i != n // i:
                count += 1
    return count

def minimal_time(n, k, uncertainities, experiences):
    dp = {(0, 0): 0}
    for i in range(n):
        new_dp = {}
        for spend_time in dp.keys():
            # Calculate the min division time
            for div in dp[spend_time]:
                new_time = spend_time + div
                if new_time < (2 ** 30):
                    min_time = (new_time, experiences[i])
                    if max(min_time[0], spend_time) in new_dp.keys():
                        new_dp[(max(min_time[0], spend_time), max(min_time[0], spend_time))] = min(
                            dp.get((spend_time, experiences[i]), 10**18) + div + min_time[1],
                            new_dp.get((max(min_time[0], spend_time), max(min_time[0], spend_time)), 10**18)
                        )
                    else:
                        new_dp[(max(min_time[0], spend_time), max(min_time[0], spend_time))] = min(
                            dp.get((spend_time, experiences[i]), 10**18) + div + min_time[1],
                            (new_time + exp, exp + min_time[1])
                        )
        dp = new_dp

    return dp.get((2**30, 0), -1)

