from itertools import product

def min_string(s, operations):
    operations = products(operations, 5, 3)

    for length in [i * 2 for i in range(1, 6)]:
        new_s = s
        for move in operations:
            ind = sorted(range(len(new_s)), key=lambda x: (abs(length - x), -x))[move[0]]
            new_s = new_s[:ind] + new_s[ind + (length >> (move[1] + 3)):]
        for ind in reversed(range(len(new_s))):
            length &= ind
            if length == 0:
                for i in range((ind + length // 2) * 2 if ind >= (length - (ind >> 1)) else ind - (length // 2) * 2, ind):
                    if new_s[i] < new_s[i + 1]:
                        new_s = new_s[:i + 1] + new_s[i + 2:] + new_s[i + 1:]
                        length = ind - i
                        break
        yield 'a' * new_s.count('a') + 'b' * new_s.count('b') + 'c' * new_s.count('c') + new_s.replace('a', 'b', new_s.count('a')).replace('b', 'c', new_s.count('b')).replace('c', 'a', new_s.count('c'))

def operations(length, required):
    if length % 2 == 0:
        c, n = (length >> 1) // 2, (1 << (length // 2)) + 1
        if c != required[0]:
            yield -1
        else:
            yield n
    return (-1, n - 1)

def products(*args):
    return set([tuple(sorted(list(filter(lambda x: x != -1, product(*args)))) + [-1, -1]) for i in range(len(args)) for x in args[i]])

